suppressPackageStartupMessages({library(data.table);library(GenomicRanges);library(rtracklayer);library(Biostrings);library(Rcpp);library(ggplot2)})
out='output/followup_analysis/';set.seed(260924)
a=fread('data/results/peak_analysis/figures/all_nonzero_peaks/transcript_region_bias/peak_transcript_region_annotations.tsv');tw=TwoBitFile('data/reference_followup/hg38.2bit');si=seqinfo(tw);a=a[summit_chromosome%in%seqlevels(si) & summit_start_0based>=25];a=a[summit_start_0based+25<seqlengths(si)[summit_chromosome]];gr=GRanges(a$summit_chromosome,IRanges(a$summit_start_0based-24,width=51));seqs=import(tw,which=gr);stopifnot(length(seqs)==nrow(a),all(width(seqs)==51));seqs[a$summit_strand=='-']=reverseComplement(seqs[a$summit_strand=='-']);valid=as.vector(letterFrequency(seqs,'N')==0);a=a[valid];seqs=seqs[valid];names(seqs)=a$peak_id;writeXStringSet(seqs,paste0(out,'cache/summit_windows_51nt.fa.gz'),compress=TRUE)
sourceCpp(paste0(out,'scripts/motif_shuffle.cpp'));z=dinuc_null(as.character(seqs),200,260924);n=length(seqs);nul=z$null;ob=z$observed
pos=data.table(motif_start_relative=-25:23,motif_midpoint_relative=-24:24,observed_count=ob,observed_frequency=ob/n,null_median=apply(nul,1,median)/n,null_low=apply(nul,1,quantile,.025)/n,null_high=apply(nul,1,quantile,.975)/n,enrichment=ob/rowMeans(nul),empirical_p=(1+rowSums(nul>=ob))/201,N=n,randomizations=200,seed=260924)
fwrite(pos,paste0(out,'tables/UAG_positional_frequency.tsv'),sep='\t');site=data.table(peak_id=a$peak_id,region=a$transcript_region,observed_UAG=z$per_sequence[,1],expected_UAG=z$per_sequence[,2]);fwrite(site,paste0(out,'tables/UAG_per_site.tsv.gz'),sep='\t');saveRDS(z,paste0(out,'cache/UAG_dinucleotide_null.rds'))
zones=list(all=1:49,central_motif_start_minus10_to10=16:36,flanks=c(1:15,37:49));zt=rbindlist(lapply(names(zones),function(k){j=zones[[k]];nc=colSums(nul[j,,drop=FALSE]);data.table(zone=k,observed=sum(ob[j]),expected=mean(nc),fold=sum(ob[j])/mean(nc),null_low=quantile(nc,.025),null_high=quantile(nc,.975),empirical_p=(1+sum(nc>=sum(ob[j])))/201,N=n)}));fwrite(zt,paste0(out,'tables/UAG_enrichment.tsv'),sep='\t')
p=ggplot(pos,aes(motif_start_relative,observed_frequency))+geom_ribbon(aes(ymin=null_low,ymax=null_high),fill='grey80')+geom_line(aes(y=null_median),lty=2,color='grey40')+geom_line(color='#257a83')+geom_vline(xintercept=0,lty=3)+theme_bw()+labs(x='UAG start relative to strand-oriented summit (nt)',y='Fraction of summit windows with UAG starting here',title='MSI2 UAG motif sanity check',subtitle=paste(n,'51-nt windows; 200 dinucleotide-preserving Euler-trail shuffles'))
for(e in c('png','pdf'))ggsave(paste0(out,'figures/UAG_summit_frequency.',e),p,width=10,height=6,dpi=220)
